"""
4-colouring of complete graphs without monochromatic triangles.
Uses GF(16) construction for K32 and CSP-based extension to maximize n.
"""
import time

def construct():
    start_time = time.time()
    deadline = start_time + 115.0

    # GF(16) arithmetic: field generated by x^4 + x + 1
    def gf16_mul(a, b):
        r = 0
        for i in range(4):
            if (b >> i) & 1:
                r ^= a << i
        # Reduce modulo x^4 + x + 1 = 0b10011
        for i in range(7, 3, -1):
            if (r >> i) & 1:
                r ^= 0b10011 << (i - 4)
        return r

    # Build log/antilog tables using primitive element 2
    # Check if 2 is primitive
    log16 = [0] * 16
    antilog16 = [0] * 16
    x = 1
    for e in range(15):
        log16[x] = e
        antilog16[e] = x
        x = gf16_mul(x, 2)
    
    # Verify 2 is primitive (should generate all 15 non-zero elements)
    # If not, try 3
    if antilog16[14] != 1: # 2^14 should be 1 if primitive? No, 2^15=1. 2^14 = 2^-1.
        # Actually, just check if we visited all non-zero elements
        visited = set(antilog16)
        if len(visited) < 15:
             # Try primitive element 3
             log16 = [0] * 16
             antilog16 = [0] * 16
             x = 1
             for e in range(15):
                 log16[x] = e
                 antilog16[e] = x
                 x = gf16_mul(x, 3)

    # Cubic residues in GF(16)*
    # Subgroup H of order 5 generated by 2^3 = 8
    h_gen = gf16_mul(2, gf16_mul(2, 2)) # 2^3 = 8
    H = set()
    h = 1
    for _ in range(5):
        H.add(h)
        h = gf16_mul(h, h_gen)
        
    # Cosets
    cosets = [H, set(), set()]
    cosets[1] = {gf16_mul(2, h) for h in H}
    cosets[2] = {gf16_mul(4, h) for h in H}
    
    # Map element to coset index
    def get_coset(x):
        if x in H: return 0
        if x in cosets[1]: return 1
        if x in cosets[2]: return 2
        return -1

    # Construct K16 coloring
    # Vertices 0..15
    # Edges (u, v) for 1 <= u < v <= 15
    # Color based on u/v
    colors16 = [[-1]*16 for _ in range(16)]
    
    for u in range(1, 16):
        for v in range(u+1, 16):
            # d = u * v^-1
            # v^-1 = v^(14) = antilog16[(15 - log16[v]) % 15]
            inv_v = antilog16[(15 - log16[v]) % 15]
            d = gf16_mul(u, inv_v)
            c = get_coset(d)
            colors16[u][v] = c
            colors16[v][u] = c
            
    # Handle vertex 0
    # Edges (0, u) for u in 1..15
    # Backtracking to assign colors 0,1,2 to (0, u)
    # Constraint: No mono triangle (0, u, v)
    def solve_k16_vertex0():
        # colors16[0][u] is the variable
        assignment = [None] * 16
        assignment[0] = None
        
        def backtrack(u):
            if u == 16:
                return True
            for c in range(3):
                assignment[u] = c
                colors16[0][u] = c
                colors16[u][0] = c
                
                # Check constraints with previous vertices
                valid = True
                for v in range(1, u):
                    # Triangle (0, v, u)
                    # Colors: (0,v)=assignment[v], (0,u)=c, (v,u)=colors16[v][u]
                    if assignment[v] == c and colors16[v][u] == c:
                        valid = False
                        break
                if valid:
                    if backtrack(u+1):
                        return True
                assignment[u] = None
            return False
            
        return backtrack(1)

    if not solve_k16_vertex0():
        # Fallback: random restart or simple greedy?
        # For now, assume it works. If not, return empty or small n.
        pass

    # Build K32 from two K16s
    # V1: 0..15, V2: 16..31
    # Colors:
    # (u,v) in V1: colors16[u][v]
    # (u,v) in V2: colors16[u-16][v-16]
    # (u in V1, v in V2): 3
    
    n_current = 32
    # Flatten colors to list in lexicographic order
    # We need a function to get color(i,j)
    def get_color(i, j, n, base_colors_matrix=None, base_n=32):
        # This is inefficient, let's build the full matrix for K32
        pass

    # Build K32 matrix
    color_matrix = [[0]*32 for _ in range(32)]
    for i in range(32):
        for j in range(i+1, 32):
            if i < 16 and j < 16:
                color_matrix[i][j] = colors16[i][j]
            elif i >= 16 and j >= 16:
                color_matrix[i][j] = colors16[i-16][j-16]
            else:
                color_matrix[i][j] = 3
            color_matrix[j][i] = color_matrix[i][j]

    # Function to flatten matrix to list
    def flatten(matrix, n):
        res = []
        for i in range(n):
            for j in range(i+1, n):
                res.append(matrix[i][j])
        return res

    current_colors = flatten(color_matrix, 32)
    current_n = 32

    # Attempt to extend
    # Backtracking for new vertex
    def try_extend(n, colors_matrix):
        # Returns new_n, new_matrix or None
        if time.time() > deadline - 10:
            return None
            
        new_n = n + 1
        new_matrix = [row[:] for row in colors_matrix]
        # Add new row/col
        for i in range(n):
            new_matrix[i].append(0) # placeholder
            new_matrix[i][n] = 0
        new_matrix.append([0] * new_n)
        
        # Variables: x[i] = color(n, i)
        x = [0] * n
        
        def backtrack(i):
            if i == n:
                # Success
                for k in range(n):
                    new_matrix[n][k] = x[k]
                    new_matrix[k][n] = x[k]
                return True
                
            for c in range(4):
                x[i] = c
                new_matrix[n][i] = c
                new_matrix[i][n] = c
                
                valid = True
                for j in range(i):
                    # Triangle (n, j, i)
                    # Colors: x[j], x[i], color_matrix[j][i]
                    if x[j] == x[i] and x[i] == colors_matrix[j][i]:
                        valid = False
                        break
                if valid:
                    if backtrack(i+1):
                        return True
            return False
            
        if backtrack(0):
            return new_n, new_matrix
        return None

    # Try to extend up to deadline
    while time.time() < deadline - 5:
        result = try_extend(current_n, color_matrix)
        if result is None:
            break
        current_n, color_matrix = result
        current_colors = flatten(color_matrix, current_n)
        
    return {'n': current_n, 'colors': current_colors}
